const staticRefinementList = instantsearch.connectors.connectRefinementList(
  ({ items, refine, widgetParams }, isFirtRender) => {
    const container = document.getElementById('brand-list');
    if (isFirtRender) {
      container.addEventListener('click', event => {
        const input = event.target.closest('input');
        if (input) {
          refine(input.value);
        }
      });
      return;
    }
    const list = widgetParams.values.map(staticItem => {
      const { isRefined } = items.find(
        item => item.label === staticItem.label
      ) || {
        isRefined: false,
      };
      return `
        <li>
          <label>
            <input
              type="checkbox"
              value="${staticItem.value}"
              ${isRefined ? 'checked' : ''}
            />
            ${staticItem.label}
          </label>
        </li>
      `;
    });
    container.innerHTML = `
      <ul>
        ${list.join('')}
      </ul>
    `;
  }
);
search.addWidget(
  staticRefinementList({
    attributeName: 'brand',
    values: [
      { label: 'Apple', value: 'Apple' },
      { label: 'Microsoft', value: 'Microsoft' },
    ],
  })
);
```

